import { g as getModelInfo } from "../../../../../../chunks/crud.js";
import { l as loadDetail } from "../../../../../../chunks/load.js";
import { B as BASE_API_URL } from "../../../../../../chunks/constants.js";
import "@sveltejs/kit";
import { n as nestedDeleteFormAction } from "../../../../../../chunks/actions.js";
const load = async (event) => {
  const detailData = await loadDetail({
    event,
    model: getModelInfo("asset-assessments"),
    id: event.params.id
  });
  const assetId = detailData.data.asset.id;
  const assetData = await event.fetch(`${BASE_API_URL}/assets/${assetId}/`).then((res) => res.json());
  const metricsData = await event.fetch(`${BASE_API_URL}/resilience/asset-assessments/${event.params.id}/metrics/`).then((res) => res.json());
  return {
    ...detailData,
    asset: assetData,
    aaMetrics: metricsData
  };
};
const actions = {
  delete: async (event) => {
    console.log("delete");
    return nestedDeleteFormAction({ event });
  }
};
export {
  actions,
  load
};
